// ─── Shared Components ───────────────────────────────────────────────────────

const Badge = ({ children, color = 'gray', dot, style }) => {
  const map = {
    gray: { bg: '#F3F4F6', txt: C.t700 },
    green: { bg: C.green100, txt: C.green600 },
    blue: { bg: C.blue100, txt: C.blue600 },
    orange: { bg: C.orange100, txt: C.orange600 },
    red: { bg: C.red100, txt: C.red600 },
    purple: { bg: C.purple100, txt: C.purple600 },
    dark: { bg: '#1C3A2A', txt: '#fff' },
  };
  const cs = map[color] || map.gray;
  return (
    <span style={{
      display: 'inline-flex', alignItems: 'center', gap: 5,
      padding: '2px 10px', borderRadius: 20,
      fontSize: 12, fontWeight: 500,
      background: cs.bg, color: cs.txt, ...style,
    }}>
      {dot && <span style={{ width: 6, height: 6, borderRadius: 3, background: cs.txt, display: 'inline-block' }} />}
      {children}
    </span>
  );
};

const Card = ({ children, style, onClick, className = '', ...p }) => (
  <div className={`mis-card${className ? ` ${className}` : ''}`} onClick={onClick} style={{
    background: C.card, borderRadius: 19, border: `1px solid ${C.border}`,
    boxShadow: '0 8px 24px rgba(15,23,42,0.035)',
    cursor: onClick ? 'pointer' : undefined,
    transition: onClick ? 'transform .15s ease, box-shadow .15s ease' : undefined,
    ...style,
  }} {...p}>{children}</div>
);

const ProgressBar = ({ value = 0, color, height = 6, style }) => {
  const col = color || (value >= 80 ? C.green500 : value >= 50 ? C.blue500 : value >= 30 ? C.orange500 : C.red500);
  return (
    <div style={{ background: '#E5E7EB', borderRadius: height, height, overflow: 'hidden', ...style }}>
      <div style={{ width: `${Math.min(100, Math.max(0, value))}%`, height: '100%', background: col, borderRadius: height, transition: 'width 0.4s ease' }} />
    </div>
  );
};

const StatCard = ({ label, value, sub, subColor, icon, style }) => (
  <Card style={{ padding: '20px 24px', ...style }}>
    <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'flex-start' }}>
      <div>
        <div style={{ fontSize: 13, color: C.t500, marginBottom: 8 }}>{label}</div>
        <div style={{ fontSize: 34, fontWeight: 700, color: C.t900, lineHeight: 1 }}>{value}</div>
        {sub && <div style={{ marginTop: 10 }}>{sub}</div>}
      </div>
      {icon && <div style={{ color: C.t300 }}>{icon}</div>}
    </div>
  </Card>
);

const Avatar = ({ name = '', size = 36, bg = '#1C3A2A', style }) => {
  const initials = name.trim().split(/\s+/).slice(0, 2).map(w => w[0]).join('').toUpperCase();
  const colors = ['#1C3A2A','#1e40af','#7c3aed','#b45309','#0f766e','#9f1239','#374151'];
  const autoBg = colors[name.charCodeAt(0) % colors.length];
  return (
    <div style={{
      width: size, height: size, borderRadius: size,
      background: bg === '#1C3A2A' ? autoBg : bg,
      color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center',
      fontSize: size * 0.36, fontWeight: 700, flexShrink: 0, ...style,
    }}>{initials || '?'}</div>
  );
};

const Btn = ({ children, variant = 'primary', size = 'md', onClick, style, disabled, icon, type = 'button' }) => {
  const v = {
    primary: { background: '#171717', color: '#fff', border: 'none' },
    secondary: { background: '#fff', color: C.t700, border: `1.5px solid ${C.border}` },
    ghost: { background: 'transparent', color: C.t700, border: 'none' },
    green: { background: C.navActive, color: '#fff', border: 'none' },
    danger: { background: C.red600, color: '#fff', border: 'none' },
    outline: { background: '#fff', color: C.t900, border: `1.5px solid ${C.t900}` },
  };
  const sz = { sm: { padding: '7px 14px', fontSize: 12 }, md: { padding: '10px 20px', fontSize: 13 }, lg: { padding: '13px 28px', fontSize: 15 } };
  return (
    <button type={type} onClick={onClick} disabled={disabled} style={{
      display: 'inline-flex', alignItems: 'center', justifyContent: 'center', gap: 7,
      borderRadius: 24, cursor: disabled ? 'not-allowed' : 'pointer',
      fontWeight: 650, fontFamily: 'inherit', opacity: disabled ? 0.45 : 1,
      boxShadow: variant === 'primary' ? '0 9px 18px rgba(0,0,0,.10)' : 'none',
      ...v[variant], ...sz[size], ...style,
    }}>{icon}{children}</button>
  );
};

const Input = ({ label, placeholder, type = 'text', value, onChange, style, iconL, iconR, hint }) => (
  <div style={{ display: 'flex', flexDirection: 'column', gap: 5, ...style }}>
    {label && <label style={{ fontSize: 13, fontWeight: 500, color: C.t700 }}>{label}</label>}
    <div style={{ position: 'relative', display: 'flex', alignItems: 'center' }}>
      {iconL && <div style={{ position: 'absolute', left: 12, color: C.t400, display: 'flex' }}>{iconL}</div>}
      <input className="mis-input" type={type} placeholder={placeholder} value={value} onChange={onChange} style={{
        width: '100%', padding: `10px ${iconR ? '38px' : '14px'} 10px ${iconL ? '38px' : '14px'}`,
        border: `1.5px solid ${C.border}`, borderRadius: 10,
        fontSize: 14, color: C.t900, background: '#fff', outline: 'none', fontFamily: 'inherit',
      }} />
      {iconR && <div style={{ position: 'absolute', right: 12, color: C.t400, display: 'flex', cursor: 'pointer' }}>{iconR}</div>}
    </div>
    {hint && <div style={{ fontSize: 12, color: C.t400 }}>{hint}</div>}
  </div>
);

const Divider = ({ label, style }) => (
  <div className="mis-divider" style={{ display: 'flex', alignItems: 'center', gap: 12, ...style }}>
    <div className="mis-divider-line" style={{ flex: 1, height: 1, background: C.border }} />
    {label && <span className="mis-divider-label" style={{ fontSize: 12, color: C.t400, whiteSpace: 'nowrap' }}>{label}</span>}
    <div className="mis-divider-line" style={{ flex: 1, height: 1, background: C.border }} />
  </div>
);

const StatusDot = ({ color = C.green500, size = 8 }) => (
  <span style={{ width: size, height: size, borderRadius: size, background: color, display: 'inline-block', flexShrink: 0 }} />
);

