const readActiveProject = () => {
  try {
    const raw = localStorage.getItem('mis_active_project');
    return raw ? { ...DEFAULT_PROJECT, ...JSON.parse(raw) } : null;
  } catch (_) { return null; }
};
const writeActiveProject = project => {
  const normalized = { ...DEFAULT_PROJECT, ...project };
  localStorage.setItem('mis_active_project', JSON.stringify(normalized));
  window.dispatchEvent(new CustomEvent('mis:project-change', { detail: normalized }));
  return normalized;
};
const clearActiveProject = () => {
  localStorage.removeItem('mis_active_project');
  window.dispatchEvent(new CustomEvent('mis:project-change', { detail: null }));
};
const openProjectDashboard = (project, onNavigate) => {
  writeActiveProject(project);
  onNavigate('dashboard');
};
const formatProjectBudget = value => {
  const numeric = Number(String(value || '').replace(/\D/g, ''));
  return numeric ? `R$ ${(numeric / 1000000).toFixed(1).replace('.', ',')}M` : 'R$ 4,2M';
};
const projectDaysRemaining = deadline => {
  if (!deadline) return 28;
  const [d, m, y] = String(deadline).split('/').map(Number);
  if (!d || !m || !y) return 28;
  const today = new Date(); today.setHours(0,0,0,0);
  return Math.max(0, Math.ceil((new Date(y, m - 1, d) - today) / 86400000));
};

